# One-click release APK build (signed + minified)
# Requires android/app/keystore.properties (release signing) - generated by the release-prep step.
# JDK 17 + Android SDK in C:\Users\Administrator\android-tools
param([switch]$AllowStaleAssets)
$ErrorActionPreference = 'Stop'
$tools = 'C:\Users\Administrator\android-tools'
$env:JAVA_HOME = "$tools\jdk-17.0.20+8"
$env:ANDROID_HOME = "$tools\sdk"
$env:ANDROID_SDK_ROOT = "$tools\sdk"

# Sync latest www into Android assets (otherwise the APK packages stale web assets)
$capCli = Join-Path $PSScriptRoot 'node_modules\@capacitor\cli\bin\capacitor'
if (Test-Path $capCli) {
  Write-Host '==> cap sync android'
  Set-Location $PSScriptRoot
  & node $capCli telemetry off 2>&1 | Out-Null
  & node $capCli sync android
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
} elseif ($AllowStaleAssets) {
  # 显式豁免才允许跳过：跳过 sync 打进 APK 的是上一次的旧 web 资源（硬规矩 9），默认 fail-closed
  Write-Warning "cap CLI not found - 已显式允许 -AllowStaleAssets：APK 里是旧 web 资源，不可发布"
} else {
  Write-Error "cap CLI 缺失：$capCli。绑定 cap sync 的脚本不能静默跳过（会打出旧 web 资源）。先在本目录 npm install；确需跳过请显式加 -AllowStaleAssets。"
  exit 1
}

# Release signing required: app/keystore.properties + release.keystore must exist
$ks = Join-Path $PSScriptRoot 'android\app\keystore.properties'
if (-not (Test-Path $ks)) {
  Write-Error "Missing $ks - release build cannot be signed. See release-prep notes."
  exit 1
}

Set-Location (Join-Path $PSScriptRoot 'android')
# cmd /c 包裹：gradle 的 stderr 输出（javac note 等）在 PS 5.1 + $ErrorActionPreference='Stop'
# 下会被当成 NativeCommandError 中断脚本；cmd 重定向后 $LASTEXITCODE 仍反映 gradlew 退出码。
cmd /c "gradlew.bat assembleRelease 2>&1"
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

$apk = Join-Path $PSScriptRoot 'android\app\build\outputs\apk\release\app-release.apk'
if (Test-Path $apk) {
  Write-Host "BUILD OK: $apk"
  # 复制为友好文件名：h_n-printer_android_v{版本号}.apk（版本号自动从 build.gradle 读取）
  # 命名约定（2026-09 起）：与桌面端 h_n-printer_setup_{版本}.exe 同一风格 —— 英文 + 下划线，
  # 避免中文名在 scp / COS / 浏览器下载时被转码，也便于和服务器以及 COS 桶里的对象名一致。
  $version = ''
  $vc = 0
  try {
    $gradleFile = Join-Path -Path $PSScriptRoot -ChildPath 'android\app\build.gradle'
    $gr = Get-Content $gradleFile -Raw -ErrorAction Stop
    $m = [regex]::Match($gr, 'versionName\s+"([^"]+)"')
    if ($m.Success) { $version = $m.Groups[1].Value }
    $mvc = [regex]::Match($gr, 'versionCode\s+(\d+)')
    if ($mvc.Success) { $vc = [int]$mvc.Groups[1].Value }
  } catch {
    Write-Warning "read versionName from build.gradle failed: $($_.Exception.Message)"
  }
  $distDir = Join-Path $PSScriptRoot 'dist'
  New-Item -ItemType Directory -Force -Path $distDir | Out-Null
  $friendly = "h_n-printer_android_v${version}.apk"
  Copy-Item $apk (Join-Path $distDir $friendly) -Force
  Write-Host "COPIED : $(Join-Path $distDir $friendly)"
  # 自动回写三份 app_update.json（2026-11-17 审计 Y6）：version/versionCode/url/md5 全由本次产物推出，
  # notes/force 保留人工填写。手工漏改会让老用户永远收不到更新，而且线上清单看着一切正常。
  if ($version -and $vc -gt 0) {
    $md5 = (Get-FileHash -Algorithm MD5 -Path $apk).Hash.ToLower()
    $manifestPaths = @(
      (Join-Path $PSScriptRoot 'app_update.json'),
      (Join-Path $PSScriptRoot 'updates\app_update.json'),
      (Join-Path $distDir 'app_update.json')
    )
    $seed = $null
    foreach ($mf in $manifestPaths) {
      if (Test-Path $mf) {
        try { $seed = Get-Content $mf -Raw -Encoding UTF8 | ConvertFrom-Json } catch { }
        if ($seed) { break }
      }
    }
    $notes = ''
    $force = $false
    if ($seed) { $notes = [string]$seed.notes; $force = [bool]$seed.force }
    $payload = [ordered]@{
      version = $version
      versionCode = [int]$vc
      url = "https://hn-space.cn/updates/$friendly"
      md5 = $md5
      notes = $notes
      force = $force
    }
    # ConvertTo-Json 默认产出 CRLF + 4 空格缩进 + 「":  "」双空格，和仓库里手写的 2 空格 / LF
    # 风格不一致，每打一次包就把三份清单整体重写一遍（diff 噪声大）。这里统一成原风格。
    $json = ($payload | ConvertTo-Json -Depth 5)
    $json = $json -replace "`r`n", "`n"
    $json = $json -replace '"(w+)":s+', '"$1": '
    $json = $json -replace "(?m)^    ", "  "
    $utf8 = New-Object System.Text.UTF8Encoding($false)
    foreach ($mf in $manifestPaths) {
      $dir = Split-Path -Parent $mf
      if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
      [System.IO.File]::WriteAllText($mf, $json + "`n", $utf8)
      Write-Host "MANIFEST: $mf ($version / versionCode $vc)"
    }
  } else {
    Write-Warning "跳过 app_update.json 回写：读不到 versionName / versionCode"
  }
  Write-Host "提示：上传到服务器 /updates/ 时保持同名，app_update.json 的 url 也用这个名字"
} else {
  Write-Host 'Build finished but release APK not found'
}
